use std :: process :: Command ; use std :: fs ; use std :: path :: Path ; use std :: time :: Instant ; fn test_performance_benchmarking () -> ZkperfTestResult { let start = Instant :: now () ; let test_name = "Performance Benchmarking" ; let benchmark_dir = "./zkperf_benchmark_output" ; if Path :: new (benchmark_dir) . exists () { let _ = std :: fs :: remove_dir_all (benchmark_dir) ; } let mut successful_benchmarks = 0 ; for i in 0 .. 3 { let iteration_dir = format ! ("{}/iteration_{}" , benchmark_dir , i) ; match Command :: new ("cargo") . args (& ["run" , "--bin" , "zkperf-record" , "--" , "run" , "./simple_repository_mathematical_atlas" , & iteration_dir]) . current_dir ("./zkperf") . output () { Ok (output) => { if output . status . success () { if Path :: new (& format ! ("{}/summary.cbor" , iteration_dir)) . exists () { successful_benchmarks += 1 ; } } } Err (_) => { } } } if successful_benchmarks >= 2 { ZkperfTestResult :: new (test_name . to_string () , true , start . elapsed () . as_millis () as u64 , Some (format ! ("{} benchmark iterations successful" , successful_benchmarks)) , None , None ,) } else { ZkperfTestResult :: new (test_name . to_string () , false , start . elapsed () . as_millis () as u64 , None , None , Some (format ! ("Only {} successful benchmark iterations" , successful_benchmarks)) ,) } }